 INPUT  OUTPUT 
12 23 34 45 0  24  
Magyarázat: 1 + 2 + 2 + 3 + 3 + 4 + 4 + 5 = 24 
Megoldás: 
#include <iostream> 
using namespace std; 
int main() { 
    int sum = 0, nr, nr1; 
    do  
    { 
        cin >> nr; 
        nr1 = nr; 
        while( nr1 )  
        { 
            sum += nr1 % 10; 
            nr1 /= 10; 
