int main() 
{ 
 int a, b; 
 cin >> a >> b; 
 if( a/10 > b/10 && (a/10 + a%10) > (b/10 + b%10) ) { cout << a; } 
 else if ( b/10 > a/10 && (b/10 + b%10) > (a/10 + a%10) ) { cout << b; } 
