void reverse(int *arr, int start, int end) { 
    while (start < end) { 
        int temp = arr[start]; 
        arr[start] = arr[end]; 
        arr[end] = temp; 
        start++; 
        end--; 
    } 
} 

void rotate(int *nums, int n, int k) { 
    k = k % n;  // k lehet nagyobb, mint n 
    // Fordítsuk meg a teljes sorozatot 
    reverse(nums, 0, n - 1); 
    // Az első k darab érék megfordítása 
    reverse(nums, 0, k - 1); 
    // A maradék, n-k érék megfordítása 
    reverse(nums, k, n - 1); 
} 

