        elem /= 10; 
    } 
    return ossz; 
} 

int szocske( int n, int *t ){ 
    int i, lepesszam = 0, volt[n] = {0}; 
    for( i = 0 ; i>=0 && i<n && !volt[i] ; i += szjossz(t[i]) ){ 
        volt[i] = 1; 
        ++lepesszam; 
    } 
    if( i>=0 && i<n ) { return -1; } 
