float atlag(int i, int j, int x [][102] ){ 
    int k = 0; 
    float s = 0; 
    for ( int ii = i-1 ; ii <= i+1 ; ++ii ){ 
        for ( int jj = j-1 ; jj <= j+1 ; ++jj ){ 
            if ( ii == i && jj == j || x[ii][jj] == 0 ){ 
                continue; 
            } 
            ++k; 
            s += x[ii][jj]; 
        } 
    } 
    return s/k; 
} 

int fuggveny ( int n, int m, int x [][102] ){ 
    int k = 0; 
    for ( int i = 1 ; i <= n ; ++i ){ 
        for ( int j = 1 ; j <= m ; ++j ){ 
            if ( x[i][j] == atlag(i,j,x) ){ 
                ++k; 
            } 
        } 
    } 
    return k; 
} 

