vagy C/C++ programot, a mely beolvassa a mátrixot,  és megkeresi azt az n elemű, szigorúan 
növekvő számsorozatot, amelynek i-edik eleme a mátrix i-edik sorából származik, és legnagyobb 
az elemeinek összege . A képernyőre csak a maximális összegértéket kell kiírni. Ha nem létezik 
egyetlen számsorozat sem, amely megfelelne a követelményeknek, akkor nullát írjon ki a program. 
Példa: 
BEMENET  KIMENET 
3   19 
1 4 6 
3 5 6 
2 2 9 
#include <stdio.h> 
int legnagyobbnalakisebb(int [][100], int, int, int); 
int main() 
{ 
    int n, a[100][100], i, j; 
    freopen("input7.txt","rt",stdin); 
    scanf("%i", &n); 
    for ( i = 0 ; i < n ; ++i ){ 
        for ( j = 0 ; j < n ; ++j ){ 
            scanf("%i", &a[i][j]); 
        } 
    } 
    //ÖTLET: az utolsó sorból az utolsó elemet válasszuk (a[n-1][n-1]) 
    //majd minden i-edik sorban (i=n-2,n-3,...0) megkeressük,  
    //amennyiben létezik ilyen, 
    //a legnagyobb olyan elemet, amely kisebb,  
    //mint az (i+1)-edik sorból választott 

    int utolso, utolsoelotti, osszeg; 
    utolso = osszeg = a[n-1][n-1]; 
    for ( i = n-2 ; i >= 0 ; --i ){ 
        utolsoelotti = legnagyobbnalakisebb(a,i,n,utolso); 
        if ( utolsoelotti == -1 ){ 
            break; 
        } 
        utolso = utolsoelotti; 
        osszeg += utolso; 
    } 

    if ( i < 0 ){ 
        printf("%i", osszeg); 
    } 
    else{ 
        printf("0"); 
    } 
    return 0; 
} 

int legnagyobbnalakisebb(int a[][100], int i, int n, int utolso){ 
//Visszatéríti az a tömb i-edik sorából a legnagyobb olyan elemet,  
//amely kisebb, mint az utolso paraméter 
//Ha nincs ilyen elem, akkor (-1)-et térít vissza 
    int j = n-1; 
    while ( j >= 0 && a[i][j] >= utolso ){ 
        --j; 
    } 
    if ( j < 0 ){ 
        return -1; 
    } 
    else{ 
        return a[i][j]; 
    } 
} 



