#include <stdio.h> 
int main() 
{ 
    int n, a[100][100], b[100] = {0}, i, j, k; 
    freopen("input8.txt","rt",stdin); 
    scanf("%i", &n); 
    for ( i = 0 ; i < n ; ++i ){ 
        for ( j = 0 ; j < n ; ++j ){ 
            scanf("%i", &a[i][j]); 
        } 
    } 
    for ( k = 0 ; k <= (n-1)/2 ; ++k ){  
        //keretről keretre haladunk, befele 
        if ( n % 2 && k == (n-1)/2){  
            //ha n páratlan, és a legbelső, egy-elemű kereten vagyunk 
            b[k] = a[k][k]; 
        } 
        else{  
            //a k. keret négy sarka 
            b[k] += a[k][k] + a[n-1-k][k] + a[n-1-k][n-1-k] + a[k][n-1-k]; 
        } 


        for ( i = k, j = k+1 ; j < n-1-k ; ++j ){  
            //a k. keret felső oldalának sarkok közé eső szakasza 
