            //középpontra való szimmetrikusait is tekintjük 
            b[k] += (a[i][j] + a[j][i] + a[n-1-i][n-1-j] + a[n-1-j][n-1-i]); 
        } 
        printf("%i\n", b[k]); 
        if ( k > 0 && b[k] > b[k-1] ){ 
            //ha elromlik a csökkenő sorrend, leállítjuk a ciklust 
