       int S; 
       scanf("%i", &S); 
       if ( S == 1 ) { printf ("-1"); } 
       else{ 
           if ( S % 5 == 0) { printf ("%i", S/5); } 
           if ( S % 5 == 1) { printf ("%i", S/5 + 1); } 
           if ( S % 5 == 2) { printf ("%i", S/5 + 1); } 
           if ( S % 5 == 3) { printf ("%i", S/5 + 1); } 
           if ( S % 5 == 4) { printf ("%i", S/5 + 2); } 
       } 
       return 0; 
   }
